@startuml

class GasStation {
  + Id : int
  + Address : string
}

class FuelPump {
  + Number : int
  + IsSelfService : boolean
}

class Fuel {
  + Name : string
  + Octane : int
}

class DailyPrice {
  + Date : date
  + PricePerLiter : float
}

class FuelPurchase {
  + Id : int
  + Liters : int
}

GasStation "1" -- "1..12" FuelPump
FuelPump "*" -- "*" Fuel

GasStation "1" -- "*" DailyPrice
Fuel "1" -- "*" DailyPrice

FuelPump "1" -- "*" FuelPurchase
Fuel "1" -- "*" FuelPurchase
DailyPrice "1" -- "*" FuelPurchase

@enduml

